require(['prototype'],function(){window.mtEmailMass=function(url,storeId){var r=confirm("Are you sure? ");if(r==true){new Ajax.Request(url,{parameters:{'store_id':storeId},loaderArea:container,onComplete:function(transport){if(transport.responseJSON.message){alert(transport.responseJSON.message);}
if(transport.responseJSON.error){alert('Error: '+transport.responseJSON.error);}}.bind(this)});}};});